<?php
declare(strict_types=1);
namespace WexaShelf;
use PDO;
/** Private bounded upload. Each transfer belongs to one live owner session. */
final class BackupTransfer {
 public const CHUNK=393216; public const MAX=104857600;
 private string $dir;
 public function __construct(private PDO $db,private Repository $repo,private array $config,private Auth $auth){$this->dir=Config::storage().'/backup-transfers';}
 private function owner():array{if(($this->auth->principal()['role']??null)!=='owner')throw new ApiException('Owner session required.',403);return ['session'=>Auth::sessionId(),'securityRevision'=>(new AccountSecurity($this->db,$this->repo,$this->config))->raw()['securityRevision']];}
 private function init():void{if(!is_dir($this->dir)&&!mkdir($this->dir,0700,true))throw new ApiException('Private transfer storage unavailable.',503);if(is_link($this->dir))throw new ApiException('Invalid transfer storage.');chmod($this->dir,0700);}
 private function read(string $id):array{Validation::check((bool)preg_match('/^[a-f0-9]{32}$/D',$id),'Invalid upload ID.');$path=$this->dir.'/'.$id.'.json';if(!is_file($path)||is_link($path))throw new ApiException('Upload not found.',404);$v=json_decode((string)file_get_contents($path),true,32,JSON_THROW_ON_ERROR);$owner=$this->owner();if(!hash_equals($v['session'],$owner['session'])||$v['securityRevision']!==$owner['securityRevision'])throw new ApiException('Upload belongs to another or revoked session.',403);if($v['expires']<time())throw new ApiException('Upload expired. Start again.',410);$applied=$this->repo->setting('backup-transfer-applied:'.$id);if(is_array($applied)&&hash_equals($v['sha256'],$applied['sha256'])){$v['status']='applied';$v['result']=$applied['result'];}return $v;}
 private function write(array $v):void{$tmp=tempnam($this->dir,'.transfer-');try{chmod($tmp,0600);if(file_put_contents($tmp,json_encode($v,JSON_THROW_ON_ERROR))===false||!rename($tmp,$this->dir.'/'.$v['id'].'.json'))throw new ApiException('Could not save upload state.',503);}finally{if(is_file($tmp))unlink($tmp);}}
 private function visible(array $v):array{return array_intersect_key($v,array_flip(['id','revision','status','bytes','received','nextIndex','sha256','expires','preview','result']));}
 public function state(?string $id=null):array{$this->owner();if($id===null)return ['maxBytes'=>self::MAX,'chunkBytes'=>self::CHUNK,'expiresInSeconds'=>3600];return $this->visible($this->read($id));}
 public static function fingerprint(array $backup):string{unset($backup['exportedAt']);return hash('sha256',json_encode($backup,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));}
 public static function decodeFile(string $file,string $sha256):array{
  Validation::check(is_file($file)&&!is_link($file)&&filesize($file)>0&&filesize($file)<=self::MAX&&preg_match('/^[a-f0-9]{64}$/D',$sha256),'Invalid local backup file or checksum.');Validation::check(hash_equals($sha256,hash_file('sha256',$file)),'Backup checksum mismatch.');$limit=trim((string)ini_get('memory_limit'));if($limit!=='-1'){$unit=strtolower(substr($limit,-1));$bytes=(int)$limit*match($unit){'g'=>1073741824,'m'=>1048576,'k'=>1024,default=>1};if(memory_get_usage(true)+filesize($file)*20+67108864>$bytes)throw new ApiException('Backup retained: this host has insufficient safe PHP memory for validation. Use the local restore CLI with a suitable memory limit.',413);}
  try{$v=json_decode((string)file_get_contents($file),true,512,JSON_THROW_ON_ERROR);}catch(\JsonException){throw new ApiException('Backup is not valid JSON.');}Validation::check(is_array($v),'Backup must be an object.');return $v;
 }
 public function action(array $input):array{
  $owner=$this->owner();$action=$input['action']??'';Validation::check(in_array($action,['start','chunk','preview','apply','cancel'],true),'Invalid backup transfer action.');$this->init();$lock=fopen($this->dir.'/lock','c');if(!$lock||!flock($lock,LOCK_EX|LOCK_NB))throw new ApiException('Another backup request is active. Retry after it finishes.',409);chmod($this->dir.'/lock',0600);
  try{
   if($action==='start'){
    Validation::check(is_int($input['bytes']??null)&&$input['bytes']>0&&$input['bytes']<=self::MAX&&is_string($input['sha256']??null)&&preg_match('/^[a-f0-9]{64}$/D',$input['sha256']),'Backup must be at most100MiB with a SHA-256 checksum.');$active=0;foreach(glob($this->dir.'/*.json')?:[]as$path){$old=json_decode((string)file_get_contents($path),true);if(is_array($old)&&($old['expires']??0)<time()&&preg_match('/^[a-f0-9]{32}\.json$/D',basename($path))){@unlink(substr($path,0,-5).'.part');$this->db->prepare('DELETE FROM ws_settings WHERE setting_key=?')->execute(['backup-transfer-applied:'.basename($path,'.json')]);unlink($path);}else $active++;}Validation::check($active<3,'Three transfers already exist. Cancel an old transfer or wait for expiry.');$id=bin2hex(random_bytes(16));$file=$this->dir.'/'.$id.'.part';$f=fopen($file,'x');if(!$f)throw new ApiException('Private upload file unavailable.',503);fclose($f);chmod($file,0600);$v=array_merge($owner,['id'=>$id,'revision'=>0,'status'=>'uploading','bytes'=>$input['bytes'],'sha256'=>$input['sha256'],'received'=>0,'nextIndex'=>0,'expires'=>time()+3600]);$this->write($v);return $this->visible($v);
   }
   Validation::check(is_string($input['id']??null),'Upload ID required.');$v=$this->read($input['id']);$file=$this->dir.'/'.$v['id'].'.part';Validation::check(is_int($input['revision']??null),'Upload revision required.');
   if($action==='chunk'){
    Validation::check(is_int($input['index']??null)&&$input['index']>=0&&is_string($input['dataBase64']??null)&&strlen($input['dataBase64'])<=524288,'Invalid upload chunk.');$data=base64_decode($input['dataBase64'],true);Validation::check($data!==false&&strlen($data)>0&&strlen($data)<=self::CHUNK,'Invalid chunk encoding.');
    if($input['index']<$v['nextIndex']){$f=fopen($file,'rb');fseek($f,$input['index']*self::CHUNK);$existing=fread($f,strlen($data));fclose($f);Validation::check(strlen($data)===min(self::CHUNK,$v['bytes']-$input['index']*self::CHUNK)&&hash_equals(hash('sha256',$existing),hash('sha256',$data)),'Retried chunk differs from saved data.');return $this->visible($v);}
   }
   if($action==='apply'&&$v['status']==='applied'&&is_string($input['previewToken']??null)&&hash_equals($v['previewTokenHash'],hash('sha256',$input['previewToken'])))return $this->visible($v);
   if($input['revision']!==$v['revision'])throw new ApiException('Upload state changed. Resume from the latest state.',409);
   switch($action){
    case 'chunk':Validation::check($v['status']==='uploading'&&$input['index']===$v['nextIndex'],'Chunks must arrive in order.');Validation::check(strlen($data)===min(self::CHUNK,$v['bytes']-$v['received']),'Chunk length does not match remaining upload.');$f=fopen($file,'c+b');if(!$f)throw new ApiException('Private upload unavailable.',503);try{if(!ftruncate($f,$v['received'])||fseek($f,$v['received'])!==0||fwrite($f,$data)!==strlen($data)||!fflush($f))throw new ApiException('Chunk could not be stored.',503);}finally{fclose($f);}$v['received']+=strlen($data);$v['nextIndex']++;if($v['received']===$v['bytes']){$v['status']='uploaded';if(!hash_equals($v['sha256'],hash_file('sha256',$file)))$v['status']='checksum-failed';}break;
    case 'preview':Validation::check(in_array($v['status'],['uploaded','previewed'],true),'Complete and verify the upload first.');$backup=self::decodeFile($file,$v['sha256']);$v['preview']=$this->repo->restoreBackup($backup,true);$v['sourceFingerprint']=$this->repo->transaction(fn()=>self::fingerprint($this->repo->exportBackup()));$token=bin2hex(random_bytes(32));$v['previewTokenHash']=hash('sha256',$token);$v['status']='previewed';break;
    case 'apply':Validation::check(in_array($v['status'],['previewed','applied'],true)&&is_string($input['previewToken']??null)&&hash_equals($v['previewTokenHash'],hash('sha256',$input['previewToken'])),'A current explicit preview confirmation is required.');if($v['status']==='applied')return $this->visible($v);$backup=self::decodeFile($file,$v['sha256']);$this->repo->restoreBackup($backup,true);$v['result']=$this->repo->transaction(function()use($backup,$v){$owner=$this->owner();if(!hash_equals($v['session'],$owner['session'])||$v['securityRevision']!==$owner['securityRevision'])throw new ApiException('Upload session revoked.',403);if(!hash_equals($v['sourceFingerprint'],self::fingerprint($this->repo->exportBackup())))throw new ApiException('Catalog changed after preview. Preview again before restoring.',409);$result=$this->repo->restoreBackup($backup);$this->repo->setSetting('backup-transfer-applied:'.$v['id'],['sha256'=>$v['sha256'],'result'=>$result]);return $result;});$v['status']='applied';break;
    case 'cancel':$this->db->prepare('DELETE FROM ws_settings WHERE setting_key=?')->execute(['backup-transfer-applied:'.$v['id']]);@unlink($file);@unlink($this->dir.'/'.$v['id'].'.json');return ['cancelled'=>true];
   }
   $v['revision']++;$this->write($v);$out=$this->visible($v);if(isset($token))$out['previewToken']=$token;return $out;
  }finally{flock($lock,LOCK_UN);fclose($lock);}
 }
}
